files=sorted(glob.glob('/app/data/sub-*/*.nwb'))
counts={name:Counter() for name in ['classification','unit_quality','anno_name_empty','electrode_group']}
for path in files:
    with h5py.File(path,'r') as f:
        for x in f['units/classification'][()]:
            if isinstance(x, bytes): x=x.decode('utf-8')
            counts['classification'][str(x)] += 1
        for x in f['units/unit_quality'][()]:
            if isinstance(x, bytes): x=x.decode('utf-8')
            counts['unit_quality'][str(x)] += 1
